@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class QuarterlyPerformanceIT {
    final InvoicingIT fixture=new InvoicingIT();QuarterlyPerformanceService performance;PerformancePublicationService publications;CostEntryService costs;String reviewer=Crypto.token();
    @BeforeAll void migrate()throws Exception{fixture.migrate();}
    @AfterAll void dispose(){fixture.dispose();}
    StaffAccountsIT base(){return fixture.base();}
    @BeforeEach void setup()throws Exception{
        fixture.setup();base().context.register(CostEntryStore.class,CostEntryService.class,QuarterlyPerformanceStore.class,QuarterlySnapshotReader.class,QuarterlyPerformanceService.class,PerformancePublicationService.class);performance=base().context.getBean(QuarterlyPerformanceService.class);publications=base().context.getBean(PerformancePublicationService.class);costs=base().context.getBean(CostEntryService.class);
        var db=base().db;for(String cap:List.of("cost.verify","performance.calculate","performance.publish","analysis.read","sensitive.drilldown","getInvoice"))db.update("INSERT INTO adc_identity.GrantCapability VALUES ('hq',?)",cap);db.update("INSERT INTO adc_identity.GrantClinicScope VALUES ('hq',2)");
        db.update("UPDATE adc_business.AppliedTreatment SET standard_units=1.00,unit_price=1000.00,subtotal=1000.00 WHERE treatment_id=71");fixture.invoices.issue(fixture.command("quarter-income"),fixture.appointment());db.update("UPDATE adc_business.Invoice SET issued_at='2026-09-30 15:59:59',created_at='2026-09-30 15:59:59'");
        db.update("INSERT INTO adc_identity.Subject VALUES ('quarter-reviewer','STAFF',true,?,NULL)",StaffAccountsIT.utc(base().now));db.update("INSERT INTO adc_identity.StaffAccount SELECT 'quarter-reviewer','quarter-reviewer','Independent verified reviewer',NULL,password_hash,false,credential_changed_at,'fixture' FROM adc_identity.StaffAccount WHERE subject_id='other'");db.update("INSERT INTO adc_identity.Session VALUES ('quarter-review-session','quarter-reviewer',?,'WEB',?,?,?,?,NULL,NULL)",Crypto.sha256(reviewer),new byte[32],StaffAccountsIT.utc(base().now),StaffAccountsIT.utc(base().now),StaffAccountsIT.utc(base().now.plusSeconds(28800)));db.update("INSERT INTO adc_identity.AccessGrant VALUES ('quarter-review-grant','quarter-reviewer','HEADQUARTERS','hq',?,NULL,NULL,NULL,'fixture',?)",StaffAccountsIT.utc(base().now),StaffAccountsIT.utc(base().now));for(long clinic:List.of(1L,2L))db.update("INSERT INTO adc_identity.GrantClinicScope VALUES ('quarter-review-grant',?)",clinic);db.update("INSERT INTO adc_identity.GrantCapability VALUES ('quarter-review-grant','performance.publish')");
    }
    @AfterEach void close(){fixture.close();}
    AtomicCommandExecutor.Command command(String operation,String key){return base().command(operation,key,key,null);}
    AtomicCommandExecutor.Command review(String key){return new AtomicCommandExecutor.Command(reviewer,"WEB","publishQuarterPerformance",key,Crypto.sha256(key),UUID.randomUUID().toString());}
    void cost(long clinic,Long dentist,String type,String amount,String source)throws Exception{costs.create(command("recordCostEntry",source),new CostEntryService.Create(Long.toString(clinic),dentist==null?null:dentist.toString(),null,null,type,amount,"2026-09-01T10:00:00+08:00",amount.equals("0.00")?"all verified costs in this clinic, quarter and type":null,source,"q3-fixture","verified original cost source"));}
    void ready()throws Exception{cost(1,22L,"MEDICAL_SUPPLY","100.00","medical");cost(1,22L,"OPERATING","200.00","operating");cost(2,21L,"MEDICAL_SUPPLY","0.00","clinic2-medical-zero");cost(2,null,"OPERATING","0.00","clinic2-operating-zero");}
    QuarterlyPerformanceService.Preparation preparation(){return new QuarterlyPerformanceService.Preparation("2026-07-01","2026-10-01","2026-11-11T00:00:00Z",List.of("1","2"),List.of(new QuarterlyPerformanceService.ClosureEvidence("1","clinic1-closed","verified ledger close",List.of()),new QuarterlyPerformanceService.ClosureEvidence("2","clinic2-closed","verified ledger close",List.of("MEDICAL_SUPPLY","OPERATING"))),"verified complete employment roster");}
    @SuppressWarnings("unchecked") List<Map<String,Object>> calculate(String key,List<String> ids)throws Exception{return (List<Map<String,Object>>)performance.calculate(command("calculateQuarterPerformance",key),new QuarterlyPerformanceService.Calculate("2026-07-01","2026-10-01","2026-11-11T00:00:00Z",List.of("1","2"),ids)).get("items");}
    List<String> prepare()throws Exception{return ((List<?>)performance.prepare(command("prepareQuarterPerformance","prepare"),preparation()).get("items")).stream().map(r->(String)((Map<?,?>)r).get("quarterly_performance_id")).toList();}
    Map<String,Object> dentist(List<Map<String,Object>> rows,long id){return rows.stream().filter(r->r.get("dentist_id").equals(Long.toString(id))).findFirst().orElseThrow();}
    @Test void realSourcesYield700Profit70IncentiveAndSeparateReview()throws Exception{ready();var ids=prepare();var rows=calculate("calculate",ids);var result=dentist(rows,22);assertEquals("700.00",result.get("net_profit"));assertEquals("70.00",result.get("incentive_amount"));assertEquals("0.00",dentist(rows,21).get("incentive_amount"));assertEquals(rows,calculate("same-input",ids));long id=Long.parseLong((String)result.get("quarterly_performance_id"));var publish=new PerformancePublicationService.Publish((String)result.get("input_hash"),"independent checked sources and R1");base().db.update("DELETE FROM adc_identity.GrantCapability WHERE grant_id='hq' AND capability_code='performance.publish'");assertThrows(DomainFailure.class,()->publications.publish(command("publishQuarterPerformance","calculate-only"),id,publish));base().db.update("INSERT INTO adc_identity.GrantCapability VALUES ('hq','performance.publish')");assertEquals("PUBLISHED",publications.publish(command("publishQuarterPerformance","separate-authorized-review"),id,publish).get("calculation_status"));assertEquals("PUBLISHED",publications.publish(review("review"),id,publish).get("calculation_status"));assertThrows(DomainFailure.class,()->performance.sources(reviewer,"WEB",id,UUID.randomUUID().toString()));}
    @Test void missingPreparationPersistsIncompleteInsteadOfMakingUpZero()throws Exception{var result=dentist(calculate("missing",List.of()),22);assertEquals("INCOMPLETE",result.get("calculation_status"));assertNull(result.get("net_profit"));assertFalse(((List<?>)result.get("incomplete_reasons")).isEmpty());assertThrows(DomainFailure.class,()->publications.publish(review("deny-incomplete"),Long.parseLong((String)result.get("quarterly_performance_id")),new PerformancePublicationService.Publish((String)result.get("input_hash"),"review missing sources")));}
    @Test void explicitZeroCostsStillNeedConfirmedScopeAndValidZeroProfitCanBePublished()throws Exception{
        cost(1,22L,"MEDICAL_SUPPLY","100.00","medical");cost(1,22L,"OPERATING","200.00","operating");cost(2,21L,"MEDICAL_SUPPLY","0.00","clinic2-medical-zero");var missing=dentist(calculate("missing-zero-scope",prepare()),21);assertEquals("INCOMPLETE",missing.get("calculation_status"));assertTrue(missing.get("incomplete_reasons").toString().contains("MISSING_ZERO_COST_SCOPE:2:OPERATING"));cost(2,null,"OPERATING","0.00","clinic2-operating-zero");var p=preparation();var corrected=new QuarterlyPerformanceService.Preparation(p.quarter_start(),p.quarter_end(),p.cutoff(),p.clinic_ids(),p.closure_evidence(),"updated independently verified zero scope");var ids=((List<?>)performance.prepare(command("prepareQuarterPerformance","correct-zero-scope"),corrected).get("items")).stream().map(r->(String)((Map<?,?>)r).get("quarterly_performance_id")).toList();var zero=dentist(calculate("valid-zero",ids),21);assertEquals("0.00",zero.get("net_profit"));assertEquals("PUBLISHED",publications.publish(review("publish-zero"),Long.parseLong((String)zero.get("quarterly_performance_id")),new PerformancePublicationService.Publish((String)zero.get("input_hash"),"verified complete zero incentive")).get("calculation_status"));
    }
    @Test void equalNormalMinutesAllocate10001AndSuspendedMinutesAreExcluded()throws Exception{cost(1,22L,"MEDICAL_SUPPLY","0.00","medical-zero");cost(1,null,"OPERATING","100.01","public-operating");cost(2,21L,"MEDICAL_SUPPLY","0.00","clinic2-medical-zero");cost(2,null,"OPERATING","0.00","clinic2-operating-zero");var db=base().db;for(long id:List.of(21L,22L))db.update("INSERT INTO adc_business.DentistSchedule VALUES (?,?,1,'2026-09-01','09:00:00','10:00:00',20,'NORMAL',NULL,?)",100+id,id,StaffAccountsIT.utc(base().now));db.update("INSERT INTO adc_business.DentistSchedule VALUES (199,22,1,'2026-09-02','09:00:00','17:00:00',20,'SUSPENDED',NULL,?)",StaffAccountsIT.utc(base().now));var p=preparation();var ready=new QuarterlyPerformanceService.Preparation(p.quarter_start(),p.quarter_end(),p.cutoff(),p.clinic_ids(),List.of(new QuarterlyPerformanceService.ClosureEvidence("1","closed1","verified zero medical",List.of("MEDICAL_SUPPLY")),p.closure_evidence().get(1)),p.personnel_verification_reference());var ids=((List<?>)performance.prepare(command("prepareQuarterPerformance","public-ready"),ready).get("items")).stream().map(r->(String)((Map<?,?>)r).get("quarterly_performance_id")).toList();var rows=calculate("public-calculate",ids);assertEquals("50.01",dentist(rows,21).get("operating_expense"));assertEquals("50.00",dentist(rows,22).get("operating_expense"));assertEquals("0.00",dentist(rows,21).get("incentive_amount"));long id=Long.parseLong((String)dentist(rows,21).get("quarterly_performance_id"));assertEquals("PUBLISHED",publications.publish(review("negative-profit"),id,new PerformancePublicationService.Publish((String)dentist(rows,21).get("input_hash"),"negative net profit independently verified")).get("calculation_status"));}
    @Test void endedAndEarlierLeaversRemainAndExactQuarterEndRevenueIsExcluded()throws Exception{ready();base().db.update("UPDATE adc_business.Dentist SET termination_date='2026-07-01' WHERE dentist_id=21");base().db.update("UPDATE adc_business.Dentist SET termination_date='2026-06-30',is_active=false WHERE dentist_id=22");base().db.update("UPDATE adc_business.Invoice SET issued_at='2026-09-30 16:00:00'");var rows=calculate("boundary",prepare());assertEquals("0.00",dentist(rows,22).get("revenue"));assertEquals("-300.00",dentist(rows,22).get("net_profit"));assertEquals("0.00",dentist(rows,22).get("incentive_amount"));assertNotNull(dentist(rows,21));}
    @Test void missingMedicalAttributionAndNonzeroPoolWithoutMinutesAreIncomplete()throws Exception{ready();base().db.update("UPDATE adc_business.CostEntry SET dentist_id=NULL WHERE source_reference='medical'");cost(1,null,"OPERATING","10.00","unallocatable");var row=dentist(calculate("missing-sources",prepare()),22);assertEquals("INCOMPLETE",row.get("calculation_status"));assertTrue(row.get("incomplete_reasons").toString().contains("MISSING_MEDICAL_DENTIST"));assertTrue(row.get("incomplete_reasons").toString().contains("MISSING_NORMAL_MINUTES"));}
    @Test void concurrentIndependentPublishersAndCorruptFrozenAllocationCannotCreateTwoCurrentVersions()throws Exception{ready();var row=dentist(calculate("calculate",prepare()),22);long id=Long.parseLong((String)row.get("quarterly_performance_id"));base().db.update("INSERT INTO adc_identity.AccessGrant VALUES ('second-independent-review','other','HEADQUARTERS','hq',?,NULL,NULL,NULL,'fixture',?)",StaffAccountsIT.utc(base().now),StaffAccountsIT.utc(base().now));for(long clinic:List.of(1L,2L))base().db.update("INSERT INTO adc_identity.GrantClinicScope VALUES ('second-independent-review',?)",clinic);base().db.update("INSERT INTO adc_identity.GrantCapability VALUES ('second-independent-review','performance.publish')");var publish=new PerformancePublicationService.Publish((String)row.get("input_hash"),"independent reviewed concurrent publish");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return publications.publish(review("publish-a"),id,publish);});var b=pool.submit(()->{start.await();return publications.publish(new AtomicCommandExecutor.Command(base().other,"WEB","publishQuarterPerformance","publish-b",Crypto.sha256("publish-b"),UUID.randomUUID().toString()),id,publish);});start.countDown();assertEquals("PUBLISHED",a.get(20,java.util.concurrent.TimeUnit.SECONDS).get("calculation_status"));assertEquals("PUBLISHED",b.get(20,java.util.concurrent.TimeUnit.SECONDS).get("calculation_status"));}assertEquals(1,base().db.queryForObject("SELECT COUNT(*) FROM adc_business.QuarterlyPerformance WHERE dentist_id=22 AND calculation_status='PUBLISHED'",Integer.class));base().db.update("UPDATE adc_business.QuarterlyPerformance SET source_snapshot=JSON_SET(source_snapshot,'$.allocations',JSON_ARRAY(JSON_OBJECT('corrupt','owned-test'))) WHERE quarterly_performance_id=?",id);assertThrows(DomainFailure.class,()->publications.publish(review("corrupt"),id,publish));}
    @Test void internalQuarterJobIsIdempotentAndCannotPublishOrReceiveASession()throws Exception{base().context.register(QuarterlyPerformanceJob.class);var job=base().context.getBean(QuarterlyPerformanceJob.class);assertTrue(job.previousQuarter());assertFalse(job.previousQuarter());assertEquals(0,base().db.queryForObject("SELECT COUNT(*) FROM adc_business.QuarterlyPerformance WHERE calculation_status='PUBLISHED'",Integer.class));assertEquals(0,base().db.queryForObject("SELECT COUNT(*) FROM adc_identity.Session s JOIN adc_identity.Subject p ON p.subject_id=s.subject_id WHERE p.subject_type='SYSTEM'",Integer.class));assertTrue(base().db.queryForObject("SELECT COUNT(*) FROM adc_business.QuarterlyPerformance WHERE calculation_status='INCOMPLETE'",Integer.class)>0);}
    @Test void negativePublicNetUsesTheSameCentRuleAndKeepsCrossQuarterReversal()throws Exception{
        ready();var original=costs.create(command("recordCostEntry","old-quarter-public"),new CostEntryService.Create("1",null,null,null,"OPERATING","100.01","2026-06-30T10:00:00+08:00",null,"old-public-source","old-quarter","verified old quarter source"));costs.reverse(command("reverseCostEntry","current-quarter-reverse"),Long.parseLong((String)original.get("cost_entry_id")),new CostEntryService.Reverse("2026-07-01T00:00:00+08:00","current-negative-public","new-quarter","verified actual reversal time","correct supplier cost"));for(long id:List.of(21L,22L))base().db.update("INSERT INTO adc_business.DentistSchedule VALUES (?,?,1,'2026-09-01','09:00:00','10:00:00',20,'NORMAL',NULL,?)",200+id,id,StaffAccountsIT.utc(base().now));var rows=calculate("negative-public",prepare());assertEquals("-50.01",dentist(rows,21).get("operating_expense"));assertEquals("150.00",dentist(rows,22).get("operating_expense"));assertEquals("50.01",dentist(rows,21).get("net_profit"));
    }
    @Test void repeatableReadSnapshotDoesNotMixAConcurrentCommittedCost()throws Exception{
        ready();var db=base().db;var delegate=new QuarterlyPerformanceStore(db){@Override public com.adc.domain.performance.QuarterlyCalculation.Input capture(String start,String end,String cutoff,List<Long> clinics,List<com.adc.domain.performance.QuarterlyCalculation.Closure> closures,String reference,String preparer){assertEquals("REPEATABLE-READ",db.queryForObject("SELECT @@transaction_isolation",String.class));int count=db.queryForObject("SELECT COUNT(*) FROM adc_business.CostEntry",Integer.class);try(var pool=java.util.concurrent.Executors.newSingleThreadExecutor()){pool.submit(()->{try{cost(1,22L,"OPERATING","9.00","concurrent-snapshot-source");}catch(Exception failure){throw new RuntimeException(failure);}}).get(20,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception failure){throw new RuntimeException(failure);}assertEquals(count,db.queryForObject("SELECT COUNT(*) FROM adc_business.CostEntry",Integer.class));return super.capture(start,end,cutoff,clinics,closures,reference,preparer);}};
        base().context.registerBean("snapshotProbe",QuarterlySnapshotReader.class,()->new QuarterlySnapshotReader(delegate));var snapshot=base().context.getBean("snapshotProbe",QuarterlySnapshotReader.class).capture("2026-07-01","2026-10-01",base().now.toString(),List.of(1L,2L),List.of(),null,null);assertTrue(snapshot.costs().stream().noneMatch(c->c.source().equals("concurrent-snapshot-source")));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM adc_business.CostEntry WHERE source_reference='concurrent-snapshot-source'",Integer.class));
    }
    @Test void preparationDoesNotExposeUnrelatedEarlierLeaversAssignmentsOutsideItsScope()throws Exception{ready();var db=base().db;db.update("INSERT INTO adc_business.Clinic VALUES (3,'UNRELATED-C3','Unrelated clinic',NULL,'000',NULL,NULL,false,?)",StaffAccountsIT.utc(base().now));db.update("INSERT INTO adc_business.Dentist (dentist_id,employee_number,full_name,date_of_birth,home_address,phone,email,hire_date,is_active,created_at,termination_date) VALUES (23,'UNRELATED-D23','Unrelated earlier leaver','1980-01-01',NULL,'000',NULL,'2010-01-01',false,?,'2019-12-31')",StaffAccountsIT.utc(base().now));db.update("INSERT INTO adc_business.DentistClinicAssignment VALUES (333,23,3,'2010-01-01',NULL,'inactive historical assignment',false)");var ids=prepare();var store=base().context.getBean(QuarterlyPerformanceStore.class);var input=QuarterlyPerformanceService.input(store.get(Long.parseLong(ids.getFirst()),false));assertFalse(input.clinics().contains(3L));assertTrue(input.assignments().stream().noneMatch(a->a.dentist()==23 || a.clinic()==3));assertTrue(input.personnel().stream().noneMatch(d->d.id()==23));}
    @Test void sourceCorrectionMakesANewVersionAndPublishFailureKeepsCurrent()throws Exception{ready();var first=dentist(calculate("first",prepare()),22);long oldId=Long.parseLong((String)first.get("quarterly_performance_id"));publications.publish(review("first-publish"),oldId,new PerformancePublicationService.Publish((String)first.get("input_hash"),"first independent review"));cost(1,22L,"OPERATING","10.00","extra-operating");var newPreparation=new QuarterlyPerformanceService.Preparation(preparation().quarter_start(),preparation().quarter_end(),preparation().cutoff(),preparation().clinic_ids(),preparation().closure_evidence(),"updated complete employment and source verification");var newIds=((List<?>)performance.prepare(command("prepareQuarterPerformance","updated-preparation"),newPreparation).get("items")).stream().map(r->(String)((Map<?,?>)r).get("quarterly_performance_id")).toList();var next=dentist(calculate("next",newIds),22);assertEquals("690.00",next.get("net_profit"));assertNotEquals(first.get("input_hash"),next.get("input_hash"));long id=Long.parseLong((String)next.get("quarterly_performance_id"));try(var c=base().connection("inspector");var sql=c.createStatement()){sql.execute("CREATE TRIGGER adc_business.adc_test_publication BEFORE UPDATE ON adc_business.QuarterlyPerformance FOR EACH ROW BEGIN IF NEW.calculation_status='PUBLISHED' AND OLD.calculation_status='CALCULATED' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='owned publish failure'; END IF; END");try{assertThrows(org.springframework.dao.DataAccessException.class,()->publications.publish(review("failure"),id,new PerformancePublicationService.Publish((String)next.get("input_hash"),"replacement reviewed")));}finally{sql.execute("DROP TRIGGER adc_business.adc_test_publication");}}assertEquals("PUBLISHED",base().db.queryForObject("SELECT calculation_status FROM adc_business.QuarterlyPerformance WHERE quarterly_performance_id=?",String.class,oldId));publications.publish(review("replacement"),id,new PerformancePublicationService.Publish((String)next.get("input_hash"),"replacement reviewed"));assertEquals("SUPERSEDED",base().db.queryForObject("SELECT calculation_status FROM adc_business.QuarterlyPerformance WHERE quarterly_performance_id=?",String.class,oldId));assertEquals(1,base().db.queryForObject("SELECT COUNT(*) FROM adc_business.QuarterlyPerformance WHERE dentist_id=22 AND calculation_status='PUBLISHED'",Integer.class));}
}
